mapper.select:
select
a.log_id,
a.trace_id,
a.log_type,
a.ip,
a.title,
a.state,
a.content,
a.user_id,
a.user_name,
a.request_origin,
a.request_path,
a.request_method,
a.create_time
from sys_operate_log a
where 1 = 1
 and a.log_id = #{logId, jdbcType=BIGINT}
 and a.trace_id = #{traceId, jdbcType=VARCHAR}
 and a.log_type = #{logType, jdbcType=VARCHAR}
 and a.ip = #{ip, jdbcType=VARCHAR}
 and a.title = #{title, jdbcType=VARCHAR}
 and a.state = #{state, jdbcType=INTEGER}
 and a.content = #{content, jdbcType=VARCHAR}
 and a.user_id = #{userId, jdbcType=BIGINT}
 and a.user_name = #{userName, jdbcType=VARCHAR}
 and a.request_origin = #{requestOrigin, jdbcType=VARCHAR}
 and a.request_path = #{requestPath, jdbcType=VARCHAR}
 and a.request_method = #{requestMethod, jdbcType=INTEGER}
 and a.create_time = #{createTime, jdbcType=TIMESTAMP}

